const D = { energy:.6, density:.55, scale:1, hue:34, speed:1, x:.5, y:.5, alpha:.92, angle:.15, style:'engraving', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const t = K.t;
const drift = 0.9*Math.sin(t*0.61) + 0.5*Math.sin(t*1.43+1.7) + 0.32*Math.sin(t*2.29);
const swell = (K.swell!=null ? K.swell : 0.5+0.5*Math.sin(t*0.4));
const fr = i => { const s = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return s - Math.floor(s); };
const diag = Math.hypot(width, height);

// ---- style ----
const st = P.style;
let ground, ink, wob=0, doubled=false;
if (st==='sanguine'){ ground=[26,26,80]; ink=[8,72,52]; wob=0.4; }
else if (st==='blueprint'){ ground=[212,66,34]; ink=[205,12,100]; }         // white hatch on blue
else if (st==='graphite'){ ground=[40,6,74]; ink=[220,8,26]; wob=0.6; doubled=true; }
else if (st==='biro'){ ground=[42,10,82]; ink=[224,72,42]; wob=0.5; doubled=true; }
else { ground=[38,22,77]; ink=[28,34,14]; }                                  // engraving: ink on warm ivory

const cx = P.x*width, cy = P.y*height;
const baseAng = P.angle*Math.PI;
const inkA = (34 + 46*P.energy) * P.alpha;
const spacing = u*(0.014 + 0.03*(1-P.density)) * (0.7+0.6*P.scale);

function hatchField(ang, alpha, sp, wobble){
  push(); translate(cx, cy); rotate(ang);
  stroke(ink[0], ink[1], ink[2], alpha);
  strokeWeight(Math.max(0.8, u*0.0012*(st==='graphite'?1.4:1)));
  const half = diag*0.75;
  for (let x=-half; x<=half; x+=sp){
    const w2 = wobble ? wobble*sp*Math.sin(x*0.05+t*0.4) : 0;
    if (doubled){
      line(x-sp*0.14, -half, x-sp*0.14+w2, half);
      line(x+sp*0.14, -half, x+sp*0.14+w2, half);
    } else {
      line(x, -half, x+w2, half);
    }
  }
  pop();
}

push();
// toned paper ground (opaque -> luminance carrier)
blendMode(BLEND); noStroke();
fill(ground[0], ground[1], ground[2], 100*P.alpha);
rect(0,0,width,height);
// faint paper mottle
for (let i=0;i<10;i++){
  fill(ground[0], ground[1]*0.8, ground[2]*(0.92+0.12*fr(i)), 8*P.alpha);
  ellipse(fr(i*2+1)*width, fr(i*2+2)*height, (0.3+0.4*fr(i+3))*width, (0.3+0.4*fr(i+4))*height);
}

// two base hatch families across the whole frame (the tone)
blendMode(st==='blueprint' ? SCREEN : MULTIPLY);
hatchField(baseAng,            inkA*0.62, spacing,      wob);
hatchField(baseAng+Math.PI/2,  inkA*0.5,  spacing*1.15, wob);

// moving shade patches: local denser cross-hatch (3rd/4th angle) inside clipped blobs
const nP = Math.round(2 + 4*P.density);
for (let i=0;i<nP;i++){
  const ph = fr(i*4+1)*Math.PI*2;
  const rr = u*(0.22+0.28*fr(i*4+2));
  const ox = cx + Math.cos(ph + t*(0.03+0.02*fr(i))*P.speed + drift*0.4) * width*0.34*(0.5+fr(i*4+3));
  const oy = cy + Math.sin(ph*1.3 + t*(0.025+0.02*fr(i+1))*P.speed) * height*0.32*(0.5+fr(i*4+4));
  const ctx = drawingContext; ctx.save();
  ctx.beginPath();
  // soft-ish blob via many-vertex circle
  for (let a=0;a<=24;a++){
    const aa=a/24*Math.PI*2; const wob2=1+0.28*Math.sin(aa*3+ph);
    const px=ox+Math.cos(aa)*rr*wob2, py=oy+Math.sin(aa)*rr*wob2;
    if (a===0) ctx.moveTo(px,py); else ctx.lineTo(px,py);
  }
  ctx.clip();
  blendMode(st==='blueprint' ? SCREEN : MULTIPLY);
  hatchField(baseAng+0.9,        inkA*0.6, spacing*0.9, wob);
  hatchField(baseAng-0.6,        inkA*0.55, spacing*1.0, wob);
  // deepen tone
  noStroke(); fill(ink[0], ink[1], ink[2], (16+18*P.energy)*P.alpha*(0.6+0.4*swell));
  rect(ox-rr*1.4, oy-rr*1.4, rr*2.8, rr*2.8);
  ctx.restore();
}

pop();
blendMode(BLEND);
drawingContext.shadowBlur = 0;
